A readable interpreter loop with validation and a safe operator table.

```python
import operator

OPS = {'+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.truediv}

def calculate(left, op, right):
    if op not in OPS:
        raise ValueError(f'unknown operator {op!r}')
    if op == '/' and right == 0:
        raise ZeroDivisionError('cannot divide by zero')
    return OPS[op](left, right)

def main():
    while True:
        raw = input('calc> ').strip()
        if raw in ('q', 'quit'):
            break
        parts = raw.split()
        if len(parts) != 3:
            print('use: number operator number')
            continue
        try:
            left, op, right = float(parts[0]), parts[1], float(parts[2])
            print(calculate(left, op, right))
        except (ValueError, ZeroDivisionError) as err:
            print('error:', err)

if __name__ == '__main__':
    main()
```

Parsing and calculating are separate so each can be tested. Never `eval()` user input.

Download JSON with a timeout, handle HTTP errors and write it to disk only when it parsed correctly.

```python
import json
from pathlib import Path
from urllib.error import HTTPError, URLError
from urllib.request import urlopen

URL = 'https://api.github.com/repos/python/cpython'

def fetch(url, timeout=10):
    with urlopen(url, timeout=timeout) as response:
        return json.load(response)

try:
    data = fetch(URL)
except HTTPError as err:
    print('http error', err.code, err.reason)
except URLError as err:
    print('network error', err.reason)
except json.JSONDecodeError as err:
    print('not json:', err)
else:
    Path('repo.json').write_text(json.dumps(data, indent=2), encoding='utf-8')
    print('saved stars:', data.get('stargazers_count'))
```

Separate fetching from saving so a failed parse cannot leave a half-written file. `timeout` stops a dead server from hanging the script.
